Q: JPA foreign key without entity A: <p>I have been looking all over to find an answer for this and can't find one.</p>
<p>A possible work around is to define the entire entity to force JPA to create the foreign keys, but refrain from providing getters/setters for the objects. It would potentially look like this for you:</p>
<p>(note that I have not used lombok before, but the idea is that the objects are not provided in the constructor, nor do they have getters or setters, therefore users of the object know what to expect - according to the docs this should work in lombok)</p>
<pre><code>@Data
@Entity
@Table(name = &quot;favorite&quot;, schema = &quot;public&quot; , uniqueConstraints = {
    @UniqueConstraint(columnNames = {&quot;user_id&quot;, &quot;business_id&quot;})
})
public class Favorite {
  @Id
  @GeneratedValue(strategy = GenerationType.IDENTITY)
  private Long id;

  @Column(name = &quot;appuser_id&quot;)
  @NotNull
  private UUID appuser_id;

  @Column(name = &quot;business_id&quot;)
  @NotNull
  private Long businessId;


  //define foreign keys for jpa
  @ManyToOne(fetch = FetchType.LAZY, optional=false)
  @JoinColumn(name = &quot;appuser_id&quot;, referencedColumnName=&quot;id&quot;, insertable = false,
            updatable = false,
            nullable = false)
  @Getter(value=AccessLevel.NONE)
  @Setter(value=AccessLevel.NONE)
  private AppUser appUser = null; //null set for lombok to avoid creating constructor argument - jpa doesnt care 

  @ManyToOne(fetch = FetchType.LAZY, optional = false)
  @JoinColumn(name = &quot;business_id&quot;, referencedColumnName=&quot;id&quot;, insertable = false,
            updatable = false,
            nullable = false)
  @Getter(value=AccessLevel.NONE)
  @Setter(value=AccessLevel.NONE)
  private Business business = null;
}
</code></pre>
<p>Edit: I have now tested this on my own project using lombok and seems to work</p>

Q: Converting C# to apk using xamarin A: <pre><code>using UnityEngine;
using UnityEngine.UI;
using System.Collections;

public class FighterController : MonoBehaviour
{
    [Header(&quot;Character Settings&quot;)]
    public bool isAI = false;
    public float health = 100f;
    public float speed = 5f;
    public float jumpForce = 10f;
    public Slider healthBar;

    [Header(&quot;Combat Settings&quot;)]
    public Transform attackPoint;
    public float attackRange = 0.5f;
    public LayerMask opponentLayer;
    public float punchDamage = 10f;
    public float kickDamage = 15f;

    private Rigidbody2D rb;
    private Animator anim;
    private bool isGrounded;
    private Transform playerTransform; // AI এর জন্য প্লেয়ারকে চেনার জন্য

    void Start()
    {
        rb = GetComponent&lt;Rigidbody2D&gt;();
        anim = GetComponent&lt;Animator&gt;();
        if (isAI) playerTransform = GameObject.FindGameObjectWithTag(&quot;Player&quot;).transform;
    }

    void Update()
    {
        if (health &lt;= 0) return;

        if (isAI)
        {
            HandleAIBehavior();
        }
        else
        {
            HandlePlayerInput();
        }
    }

    // --- PLAYER LOGIC ---
    void HandlePlayerInput()
    {
        // Movement
        float move = Input.GetAxisRaw(&quot;Horizontal&quot;);
        rb.velocity = new Vector2(move * speed, rb.velocity.y);
        anim.SetFloat(&quot;Speed&quot;, Mathf.Abs(move));

        // Jump
        if (Input.GetKeyDown(KeyCode.W) &amp;&amp; isGrounded)
        {
            rb.AddForce(Vector2.up * jumpForce, ForceMode2D.Impulse);
            anim.SetTrigger(&quot;Jump&quot;);
        }

        // Attacks
        if (Input.GetKeyDown(KeyCode.J)) StartCoroutine(PerformAttack(&quot;Punch&quot;, punchDamage));
        if (Input.GetKeyDown(KeyCode.K)) StartCoroutine(PerformAttack(&quot;Kick&quot;, kickDamage));
        if (Input.GetKeyDown(KeyCode.L)) anim.SetTrigger(&quot;Special&quot;);
    }

    // --- AI LOGIC ---
    void HandleAIBehavior()
    {
        float distance = Vector2.Distance(transform.position, playerTransform.position);

        if (distance &gt; 1.5f)
        {
            // Move towards player
            float dir = (playerTransform.position.x &gt; transform.position.x) ? 1 : -1;
            rb.velocity = new Vector2(dir * (speed * 0.6f), rb.velocity.y);
            anim.SetFloat(&quot;Speed&quot;, 1f);
        }
        else
        {
            rb.velocity = Vector2.zero;
            anim.SetFloat(&quot;Speed&quot;, 0f);

            // Random Attack
            if (Random.value &lt; 0.01f) 
            {
                string attackType = (Random.value &gt; 0.5f) ? &quot;Punch&quot; : &quot;Kick&quot;;
                float dmg = (attackType == &quot;Punch&quot;) ? punchDamage : kickDamage;
                StartCoroutine(PerformAttack(attackType, dmg));
            }
        }
    }

    // --- COMBAT SYSTEM ---
    IEnumerator PerformAttack(string triggerName, float damage)
    {
        anim.SetTrigger(triggerName);

        // অ্যাটাক অ্যানিমেশনের সাথে সিঙ্ক করার জন্য সামান্য ওয়েট
        yield return new WaitForSeconds(0.2f);

        Collider2D[] hitOpponents = Physics2D.OverlapCircleAll(attackPoint.position, attackRange, opponentLayer);

        foreach (Collider2D opponent in hitOpponents)
        {
            if (opponent.gameObject != gameObject)
            {
                opponent.GetComponent&lt;FighterController&gt;().TakeDamage(damage);
            }
        }
    }

    public void TakeDamage(float damage)
    {
        health -= damage;
        if (healthBar != null) healthBar.value = health / 100f;

        anim.SetTrigger(&quot;Hit&quot;);

        if (health &lt;= 0)
        {
            anim.SetTrigger(&quot;Knockdown&quot;);
            this.enabled = false; // ক্যারেক্টার মারা গেলে স্ক্রিপ্ট বন্ধ হবে
        }
    }

    // Physics Check
    private void OnCollisionEnter2D(Collision2D collision)
    {
        if (collision.gameObject.CompareTag(&quot;Ground&quot;)) isGrounded = true;
    }

    private void OnCollisionExit2D(Collision2D collision)
    {
        if (collision.gameObject.CompareTag(&quot;Ground&quot;)) isGrounded = false;
    }

    // Editor-এ অ্যাটাক রেঞ্জ দেখার জন্য
    void OnDrawGizmosSelected()
    {
        if (attackPoint == null) return;
        Gizmos.DrawWireSphere(attackPoint.position, attackRange);
    }
}
</code></pre>
